ord": "work both ways", "sentence": "Trust works both ways.", "extra_examples": [{"sentence": "Flexibility works both ways: I cover your shifts, and you cover mine.", "meaning": "서로 융통성을 발휘해야죠. 제가 당신 근무를 대신하면 당신도 제 근무를 대신해주는 거예요."}, {"sentence": "Sharing a kitchen works both ways; everyone needs to clean up.", "meaning": "주방을 함께 쓰려면 서로 협조해야 해요. 모두가 뒷정리를 해야죠."}]}, {"content_index": 95, "keyword": "get the hang of", "sentence": "It took me a week to get the hang of the new app.", "extra_examples": [{"sentence": "It took a few attempts to get the hang of folding the tent.", "meaning": "텐트 접는 요령을 익히는 데 몇 번의 시도가 필요했어요."}, {"sentence": "Have you got the hang of using the ticket machine yet?", "meaning": "이제 발권기 쓰는 요령을 익혔나요?"}]}, {"content_index": 96, "keyword": "pencil in", "sentence": "Can we pencil in a meeting for Thursday morning?", "extra_examples": [{"sentence": "Could you pencil me in for a haircut next Wednesday afternoon?", "meaning": "다음 주 수요일 오후에 미용실 예약을 일단 잡아주실 수 있나요?"}, {"sentence": "We've penciled in a beach trip, but we'll check the forecast first.", "meaning": "해변 여행을 일단 잡아뒀지만 먼저 일기예보를 확인할 거예요."}]}, {"content_index": 97, "keyword": "take something offline", "sentence": "Let's take this discussion offline and continue after the meeting.", "extra_examples": [{"sentence": "This only affects our two teams, so let's take it offline after the group call.", "meaning": "이건 우리 두 팀에만 해당하니 전체 통화 후 따로 논의해요."}, {"sentence": "Could we take the pricing discussion offline to leave time for other questions?", "meaning": "다른 질문 시간도 남겨두도록 가격 논의는 따로 진행할까요?"}]}, {"content_index": 98, "keyword": "keep something on one's radar", "sentence": "Let's keep customer feedback on our radar.", "extra_examples": [{"sentence": "Keep the library's weekend workshops on your radar when planning activities for the kids.", "meaning": "아이들 활동을 계획할 때 도서관 주말 강좌도 염두에 두세요."}, {"sentence": "I'll keep that neighborhood on my radar while looking for a new apartment.", "meaning": "새 아파트를 찾는 동안 그 동네도 계속 살펴볼게요."}]}, {"content_index": 99, "keyword": "gain traction", "sentence": "The new campaign is starting to gain traction.", "extra_examples": [{"sentence": "The idea of a car-free Sunday gained traction after the successful trial.", "meaning": "시험 운영이 성공한 뒤 차 없는 일요일이라는 제안이 지지를 얻었어요."}, {"sentence": "Our podcast began to gain traction when listeners started recommending it to friends.", "meaning": "청취자들이 친구들에게 추천하기 시작하면서 우리 팟캐스트가 인기를 얻기 시작했어요."}]}]$payload$::jsonb;
  matched integer;
begin
  select count(*) into matched
  from public.contents c
  join jsonb_to_recordset(patches) as p(content_index integer, keyword text, sentence text, extra_examples jsonb)
    on c.content_index = p.content_index and c.keyword = p.keyword and c.sentence = p.sentence
  where c.status = 'published';
  -- Fresh databases contain only the 20 starter rows; generated rows are production data.
  if matched < 20 or exists (
    select 1 from public.contents c
    join jsonb_to_recordset(patches) as p(content_index integer, keyword text, sentence text)
      on c.content_index = p.content_index
    where c.keyword is distinct from p.keyword or c.sentence is distinct from p.sentence
  ) then
    raise exception 'Audited content identity mismatch (matched %)', matched;
  end if;

  update public.contents c
  set extra_examples = p.extra_examples
  from jsonb_to_recordset(patches) as p(content_index integer, keyword text, sentence text, extra_examples jsonb)
  where c.content_index = p.content_index and c.keyword = p.keyword and c.sentence = p.sentence
    and c.status = 'published';
end
$migration$;

